import pandas as pd

def expression(data):
    r = data['cfg2_top1200_residual_return']
    return r.rolling(120).mean()

from brain.alphas import alpha
import numpy as np
import numpy.typing as npt


@alpha(
    data=["cfg2_top1200_residual_return"],
    store=[],
)
def resid_reverse(data, store) -> npt.NDArray[np.float32]:
    x = data.cfg2_top1200_residual_return
    sig = -np.nanmean(x, axis=0)
    sig[~data.universe[-1].astype(bool)] = np.nan
    return sig.astype(np.float32)
